<?php
require_once __DIR__ . '/../db_connect.php';
require_once __DIR__ . '/security.php';
requireAdminAuth();
$csrf=generateCSRFToken();
$key=trim((string)EnvLoader::get('GEMINIAPIKEYFORBOOKQUESTIONS',''));
$model=trim((string)EnvLoader::get('GEMINIMODELFORBOOKQUESTIONS',EnvLoader::get('GEMINIMODEL','gemini-2.5-flash')));
$sources=['question:questions'=>['questions','id','Questions'],'question:questions_from_book'=>['questions_from_book','id','Questions from book'],'mcq:mcqs'=>['mcqs','mcq_id','MCQs'],'mcq:mcqs_from_book'=>['mcqs_from_book','mcq_id','MCQs from book']];
$source=(string)($_POST['source']??$_GET['source']??'question:questions');if(!isset($sources[$source]))$source='question:questions';$id=filter_var($_POST['record_id']??null,FILTER_VALIDATE_INT)?:0;$result=null;
$currentMap=$sources[$source];$previewRecords=[];$previewCol=str_starts_with($source,'mcq:')?'question':'question_text';
$previewStmt=$conn->prepare("SELECT {$currentMap[1]} AS record_id, {$previewCol} AS preview FROM {$currentMap[0]} ORDER BY {$currentMap[1]} DESC LIMIT 12");
if($previewStmt){$previewStmt->execute();$previewRecords=$previewStmt->get_result()->fetch_all(MYSQLI_ASSOC);$previewStmt->close();}
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!verifyCSRFToken((string)($_POST['csrf_token']??''))){http_response_code(403);exit('Invalid request token.');}
 if($key==='')$result=['ok'=>false,'title'=>'API key is missing','detail'=>'Configure GEMINIAPIKEYFORBOOKQUESTIONS.'];
 elseif(!function_exists('curl_init'))$result=['ok'=>false,'title'=>'PHP cURL is unavailable','detail'=>'Enable the PHP cURL extension.'];
 else{
  $sample=isset($_POST['sample']);$map=$sources[$source]??null;$isMcq=$map&&str_starts_with($source,'mcq:');$fields=$isMcq?['question','option_a','option_b','option_c','option_d']:['question_text'];$content=null;
  if($sample){$source='question:diagnostic:1';$fields=['question_text'];$content=['question_text'=>'What is photosynthesis?'];}
  elseif($map&&$id>0){$cols=$isMcq?'question,option_a,option_b,option_c,option_d':'question_text';$stmt=$conn->prepare("SELECT $cols FROM {$map[0]} WHERE {$map[1]}=?");$stmt->bind_param('i',$id);$stmt->execute();$content=$stmt->get_result()->fetch_assoc();$stmt->close();}
  if(!$content){$result=['ok'=>false,'title'=>$id>0?'Record was not found':'Enter a record ID','detail'=>$id>0?'No record #'.$id.' exists in '.$map[0].'. Choose one of the recent IDs below.':'Choose a source table and enter an existing record ID, or use the sample test.'];}
  else{
   $input=[['id'=>$source.($sample?'':':'.$id),'content'=>$content]];$expected=$input[0]['id'];$properties=[];foreach($fields as $field)$properties[$field]=['type'=>'STRING'];
   $schema=['type'=>'ARRAY','items'=>['type'=>'OBJECT','properties'=>['id'=>['type'=>'STRING'],'translation'=>['type'=>'OBJECT','properties'=>$properties,'required'=>$fields]],'required'=>['id','translation']]];
   $prompt="Translate all educational content into clear Urdu script used in Pakistan. Preserve scientific meaning, formulas and symbols. Return one result for each exact ID, with every requested field, using the required JSON schema.\n".json_encode($input,JSON_UNESCAPED_UNICODE);
   $url='https://generativelanguage.googleapis.com/v1beta/models/'.rawurlencode($model).':generateContent?key='.rawurlencode($key);$payload=json_encode(['contents'=>[['parts'=>[['text'=>$prompt]]]],'generationConfig'=>['responseMimeType'=>'application/json','responseSchema'=>$schema,'temperature'=>0.1]],JSON_UNESCAPED_UNICODE);
   $start=microtime(true);$ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_RETURNTRANSFER=>true,CURLOPT_CONNECTTIMEOUT=>15,CURLOPT_TIMEOUT=>90,CURLOPT_HTTPHEADER=>['Content-Type: application/json'],CURLOPT_POSTFIELDS=>$payload]);$body=curl_exec($ch);$curlError=curl_error($ch);$http=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);$duration=round(microtime(true)-$start,2);
   $api=is_string($body)?json_decode($body,true):null;$text=$api['candidates'][0]['content']['parts'][0]['text']??'';$parsed=is_string($text)?json_decode(trim(preg_replace('/^```(?:json)?\s*|\s*```$/i','',$text)??$text),true):null;
   if(is_array($parsed)){foreach(['items','results','translations'] as $wrap)if(isset($parsed[$wrap])&&is_array($parsed[$wrap])){$parsed=$parsed[$wrap];break;}}
   $entry=is_array($parsed)?($parsed[0]??$parsed[$expected]??$parsed):[];$translated=is_array($entry)?($entry['translation']??$entry):[];$valid=is_array($translated)&&($entry['id']??$expected)===$expected;foreach($fields as $field)if(!is_string($translated[$field]??null)||trim($translated[$field])==='')$valid=false;
   $detail=$curlError!==''?$curlError:(string)($api['error']['message']??'Response did not contain every requested Urdu field.');if(str_contains($detail,$key))$detail='API error details hidden.';
   $result=['ok'=>$curlError===''&&$http>=200&&$http<300&&$valid,'title'=>$curlError!==''?'Network request failed':($http<200||$http>=300?'Gemini API returned HTTP '.$http:($valid?'Gemini translation test passed':'Gemini response was incomplete')),'detail'=>$curlError!==''||$http<200||$http>=300?$detail:($valid?'Every requested field was returned in the translator response format.':'Gemini returned text but omitted or truncated one or more fields.'),'http'=>$http,'duration'=>$duration,'finish'=>$api['candidates'][0]['finishReason']??'none','tested'=>$sample?'Sample question':($map[2].' #'.$id),'sample'=>is_array($translated)?implode("\n",array_map(static fn($f)=>$f.': '.($translated[$f]??''),$fields)):(is_string($text)?$text:'')];
  }
 }
}
?>
