<?php if($result): ?><article class="result <?= $result['ok']?'pass':'fail' ?>"><h2><?= htmlspecialchars($result['title'],ENT_QUOTES,'UTF-8') ?></h2><p><?= htmlspecialchars($result['detail'],ENT_QUOTES,'UTF-8') ?></p><?php if(isset($result['http'])): ?><dl><dt>Tested</dt><dd><?= htmlspecialchars($result['tested'],ENT_QUOTES,'UTF-8') ?></dd><dt>HTTP</dt><dd><?= (int)$result['http'] ?></dd><dt>Duration</dt><dd><?= htmlspecialchars((string)$result['duration'],ENT_QUOTES,'UTF-8') ?> s</dd><dt>Finish</dt><dd><?= htmlspecialchars((string)$result['finish'],ENT_QUOTES,'UTF-8') ?></dd></dl><?php endif; ?><?php if(!empty($result['sample'])): ?><label>Gemini response<textarea readonly dir="auto" rows="5"><?= htmlspecialchars($result['sample'],ENT_QUOTES,'UTF-8') ?></textarea></label><?php endif; ?></article><?php endif; ?></section></main>
